+namespace {
+constexpr int NUM_THREADS = 8;
+
+inline void compute_rows(int n, int i0, int i1, const float* A, const float* B, float* C) {
+    for (int i = i0; i < i1; ++i) {
+        const float* Arow = A + (size_t)i * n;
+        float* Crow = C + (size_t)i * n;
+        std::fill_n(Crow, n, 0.0f);
+        for (int k = 0; k < n; ++k) {
+            float a = Arow[k];
+            const float* Brow = B + (size_t)k * n;
+            for (int j = 0; j < n; ++j) Crow[j] += a * Brow[j];
+        }
+    }
+}
